  hud.toast('PROGRESS RESET');
  hud.center(missions.mission().name, missions.mission().brief, '', 3.0);
};
$('quitBtn').onclick = () => {
  sound.click();
  state = 'title';
  buildMissionList();
  showScreen('startScreen');
  input.unlock();
};
$('againBtn').onclick = () => { sound.click(); startPlay(missions.missionIndex); };
