    this.colliders.push({ x: px, z: pz + 34, halfX: 5, halfZ: 3 });

    // A lighthouse on the point with a slowly sweeping beam.
    const lx = 150, lz = COAST_Z + 6;
    const towerMat = new THREE.MeshLambertMaterial({ color: 0xf2f2ea });
