    for (let tries = 0; tries < 14; tries++) {
      const i = 1 + Math.floor(Math.random() * (GRID - 1));
      const j = 1 + Math.floor(Math.random() * (GRID - 1));
      const along = (Math.random() - 0.5) * (PITCH - STREET_W);
